import numpy as np

def range_weights(particles, ranges, landmarks, sigma):
    """Normalised importance weights for range-only readings to landmarks with KNOWN identity.
    particles: (N, 3) array of poses (x, y, theta); ranges: (L,) measured distances;
    landmarks: (L, 2) positions; sigma: range noise standard deviation.
    Each reading is Gaussian around the true distance; readings are independent given the pose."""
    particles = np.asarray(particles, dtype=float)
    return np.full(len(particles), 1.0 / len(particles))
